  {%- if ui_def(p['Disabled'], false) %} disabled{%- endif %}
  {%- if ui_def(p['Required'], false) %} required{%- endif %}
  {%- if ui_is_set_str(ui_def(p['Role'], '')) %} role="{{ ui_def(p['Role'], '') }}"{%- endif %}
  {%- if ui_is_set_str(ui_def(p['TabIndex'], '')) %} tabindex="{{ ui_def(p['TabIndex'], '') }}"{%- endif %}
