      value="{{ ui_field(item, 'Value', '') }}"
      {%- if ui_eq(ui_field(item, 'Value', ''), ui_def(p['Value'], '')) %} selected{%- endif %}
    >{{ ui_field(item, 'Label', '') }}</option>
  {%- endfor %}
  {{ ui_def(children, '')|safe }}
</select>

